class VolumesGroup extends HttpApiGroup.make("Volumes")
  .add(HttpApiEndpoint.get("listVolumes", "/volumes", { query: ListVolumesQuery, success: ListVolumes200 })
      .middleware(APITokenSecurityMiddleware)
      .annotate(OpenApi.Identifier, "list_volumes")
      .annotate(OpenApi.Summary, "List Volumes")
      .annotate(OpenApi.Description, "Gets all existing Volumes that you have available."), 
    HttpApiEndpoint.post("createVolume", "/volumes", { payload: CreateVolumeRequestJson, success: CreateVolume201.pipe(HttpApiSchema.status(201)) })
      .middleware(APITokenSecurityMiddleware)
      .annotate(OpenApi.Identifier, "create_volume")
      .annotate(OpenApi.Summary, "Create a Volume")
      .annotate(OpenApi.Description, "Creates a new Volume attached to a Server. If you want to create a Volume that is not attached to a Server, you need to provide the `location` key instead of `server`. This can be either the ID or the name of the Location this Volume will be created in. Note that a Volume can be attached to a Server only in the same Location as the Volume itself.\n\nSpecifying the Server during Volume creation will automatically attach the Volume to that Server after it has been initialized. In that case, the `next_actions` key in the response is an array which contains a single `attach_volume` action.\n\nThe minimum Volume size is 10GB and the maximum size is 10TB (10240GB).\n\nA volume’s name can consist of alphanumeric characters, dashes, underscores, and dots, but has to start and end with an alphanumeric character. The total length is limited to 64 characters. Volume names must be unique per Project.\n\n#### Operation specific errors\n\n| Status | Code | Description |\n| --- | --- | --- |\n| `422` | `no_space_left_in_location` | There is no volume space left in the given location |"), 
    HttpApiEndpoint.delete("deleteVolume", "/volumes/:id", { params: DeleteVolumePathParams, success: HttpApiSchema.Empty(204) })
      .middleware(APITokenSecurityMiddleware)
      .annotate(OpenApi.Identifier, "delete_volume")
      .annotate(OpenApi.Summary, "Delete a Volume")
      .annotate(OpenApi.Description, "Deletes a volume. All Volume data is irreversibly destroyed. The Volume must not be attached to a Server and it must not have delete protection enabled."))
  .annotate(OpenApi.Description, "A Volume is a highly-available, scalable, and SSD-based block storage for Servers.\n\nPricing for Volumes depends on the Volume size and Location, not the actual used storage.\n\nPlease see [Hetzner Docs](https://docs.hetzner.com/cloud/#Volumes) for more details about Volumes.") {}

